<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> PAGE_DIR_SLOT_DECISION</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      8</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 每8条记录设置一个槽位</span></span>
